 IEnumerator Start(){Directory.CreateDirectory(Folder);File.WriteAllText(Folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("o"));Application.logMessageReceived+=Error;yield return SportsProbeScene.Ensure<FieldGoalMatch>("TruckFieldGoal");yield return null;var m=FindAnyObjectByType<FieldGoalMatch>();var c=m.GetComponent<FieldGoalCrowd>();Check(c!=null&&c.Spectators==2304&&c.nearFans.Length==32,"saved real stadium has2304 existing-character spectators with32 live animators");int staticFans=0;foreach(var batch in c.batches){staticFans+=batch.fans.Length;Check(batch.fans.All(f=>f!=null&&f.GetComponent<Renderer>()!=null&&f.GetComponents<Collider>().Length==0)&&batch.materials.All(mat=>mat.enableInstancing),"posed crowd uses real collider-free Unity renderers and shared instanced materials");}Check(staticFans==2272,"all2272 distant spectators remain visible to normal and manually rendered cameras");m.setup.count=4;m.AllBots();foreach(var player in m.setup.players)player.difficulty=LWS.TruckBowling.BowlingDifficulty.Hard;m.weatherPresets.Select(m.weatherPresets.entries.First(p=>p.displayName=="Clear").id);Check(m.StartMatch(),"four-AI physical kick match starts");Time.timeScale=3;float until=Time.realtimeSinceStartup+110;while(m.Live&&m.rules.goals.Sum()==0&&Time.realtimeSinceStartup<until)yield return null;Time.timeScale=1;Check(m.rules.goals.Sum()>0&&c.Reactions==m.rules.attempts.Sum(),"actual bumper contact and legal goal trigger exactly one authoritative crowd reaction");m.Pause();Check(c.Mood=="CHEER"||c.Mood=="ROAR","real successful goal selects cheering rather than constant applause");Check(c.batches.All(b=>b.fans.All(f=>f.sharedMesh==b.cheer)),"distant spectators display their visibly different baked cheering poses");var camera=m.cameraRig.view;var position=camera.transform.position;var rotation=camera.transform.rotation;float field=camera.fieldOfView;m.enabled=false;camera.transform.SetPositionAndRotation(new Vector3(80,39,-52),Quaternion.LookRotation(new Vector3(0,8,30)-new Vector3(80,39,-52)));camera.fieldOfView=65;var planes=GeometryUtility.CalculateFrustumPlanes(camera);int visible=c.batches.Sum(b=>b.fans.Count(f=>GeometryUtility.TestPlanesAABB(planes,f.GetComponent<Renderer>().bounds)));Check(visible>150,"stadium overview actually contains a large rendered crowd · visible="+visible);m.menus.Show(SportsEventScreen.Play);yield return new WaitForSecondsRealtime(.25f);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)})SportsControlledCapture.Save(m,size.x,size.y,Folder+"/real-goal-crowd-"+size.x+"x"+size.y+".png");m.menus.Show(SportsEventScreen.Pause);var crowdRoot=c.batches[0].fans[0].transform.parent.gameObject;yield return SampleFrames(camera,"crowd on");crowdRoot.SetActive(false);yield return SampleFrames(camera,"crowd hidden");crowdRoot.SetActive(true);camera.transform.SetPositionAndRotation(position,rotation);camera.fieldOfView=field;m.enabled=true;int locked=c.Reactions;var goals=(int[])m.rules.goals.Clone();m.Resume();m.Resolve(false,"must stay ignored",Vector3.zero);Check(c.Reactions==locked&&goals.SequenceEqual(m.rules.goals),"later callbacks cannot duplicate crowd feedback or revoke a legal goal");m.Resume();
  var antics=m.GetComponent<FieldGoalStadiumAntics>();Check(antics!=null&&antics.jugs.Length==8&&antics.invader.HasJointedRagdoll,"saved stadium reuses eight owned canister props and the actual Taxi jointed ragdoll");
  int jumps=antics.Jumps,scuffles=antics.Scuffles,tosses=antics.Tosses;antics.PerformAntic(0);yield return new WaitForSeconds(.2f);Check(antics.Jumps==jumps+1,"explicit jumping fixture moves an existing animated spectator");yield return new WaitForSeconds(2.2f);antics.PerformAntic(1);yield return new WaitForSeconds(.65f);Check(antics.Scuffles==scuffles+1,"paired shout/lean scuffle choreography runs");yield return new WaitForSeconds(1.8f);antics.PerformAntic(2);yield return new WaitForSeconds(.3f);Check(antics.Tosses==tosses+1&&antics.jugs.Any(j=>j.gameObject.activeSelf),"pooled sealed jug is visibly airborne and collider-free");Check(antics.jugs.All(j=>j.GetComponentsInChildren<Collider>(true).Length==0),"jug antics cannot obstruct a kick or score");yield return new WaitForSeconds(1.7f);
  // Force only the rare presentation event; the legal kick above was real PhysX.
  if(!m.rules.AttemptLocked){m.Resolve(false,"Explicit vignette-only fixture",Vector3.zero);}var savedGoals=(int[])m.rules.goals.Clone();var savedAttempts=(int[])m.rules.attempts.Clone();int tackles=antics.Tackles;Check(antics.StartRefereeVignette(),"rare referee vignette starts only after the result is locked");yield return new WaitForSeconds(.5f);var refPosition=antics.referee.position;var fanPosition=antics.InvaderPosition;m.Pause();yield return new WaitForSecondsRealtime(.25f);Check(antics.referee.position==refPosition&&antics.InvaderPosition==fanPosition,"pause preserves both referee and pitch invader choreography");m.Resume();yield return new WaitForSeconds(1.15f);Check(antics.Tackles==tackles+1&&antics.invader.IsRagdoll,"referee reaches the fan and activates shared Taxi ragdoll exactly once");Check(antics.invader.RagdollBodies.All(b=>!b.detectCollisions)&&antics.referee.GetComponentsInChildren<Collider>(true).Length==0,"canned tackle never participates in live football collision geometry");m.Pause();m.menus.Show(SportsEventScreen.Play);yield return new WaitForSecondsRealtime(.25f);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)})SportsControlledCapture.Save(m,size.x,size.y,Folder+"/referee-tackle-"+size.x+"x"+size.y+".png");m.menus.Show(SportsEventScreen.Pause);m.Resume();yield return new WaitForSeconds(7.5f);Check(!antics.VignetteActive&&!antics.referee.gameObject.activeSelf,"referee leaves and the fixed event pool retires cleanly");Check(savedGoals.SequenceEqual(m.rules.goals)&&savedAttempts.SequenceEqual(m.rules.attempts),"wild stadium presentation cannot award or revoke any kick");
  if(c.runner.gameObject.activeSelf){m.SetupScreen();m.StartMatch();}int runs=c.RunOns;c.RunOn();Check(c.RunOns==runs+1&&c.runner.gameObject.activeSelf&&c.runner.GetComponentsInChildren<Collider>(true).Length==0,"explicit rare-event fixture starts the existing character on a noninterfering sideline route");yield return new WaitForSeconds(.55f);var moved=c.runner.position;m.Pause();yield return new WaitForSecondsRealtime(.2f);Check(c.runner.position==moved,"pause preserves the fan's exact route position");m.Resume();yield return new WaitForSeconds(.55f);Check(Vector3.Distance(moved,c.runner.position)>1&&Mathf.Abs(c.runner.position.x)>=23.9f,"fan resumes smooth travel outside the central ball corridor");m.SetupScreen();Check(!c.runner.gameObject.activeSelf&&!c.response.isPlaying,"setup cancels the rare event and crowd sound");int count=FindObjectsByType<Renderer>().Length;for(int repeat=0;repeat<3;repeat++){Check(m.StartMatch(),"rematch starts without rebuilding crowd "+repeat);yield return null;m.SetupScreen();}Check(FindObjectsByType<Renderer>().Length==count,"repeated rematches reuse the fixed audience rather than duplicating spectators");if(!Application.isEditor)yield return PlayerWorkload(m);SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindAnyObjectByType<FieldGoalCrowd>()==null&&FindObjectsByType<AudioListener>().Length==1,"menu return cleans audience callbacks and preserves one listener");report.AppendLine("CHECKS="+checks+" ERRORS="+errors+" · actual physical kick/goal; explicit forced rare-event presentation fixture. Controlled renders, not human/hardware/audio listening or Windows/GPU benchmark evidence.");File.WriteAllText(Folder+"/result.txt",report.ToString());Application.logMessageReceived-=Error;
