 IEnumerator PlayerWorkload(FieldGoalMatch m){
  Check(m.StartMatch(),"dense-crowd Windows workload starts with actual four-AI competition");Time.timeScale=1;int renders=0;var samples=new List<float>(4096);int gc=GC.CollectionCount(0);long memory=GC.GetTotalMemory(false);float start=Time.realtimeSinceStartup;bool screenshot=false;
  void Rendered(ScriptableRenderContext context,Camera camera){if(camera==m.cameraRig.view)renders++;}
  RenderPipelineManager.endCameraRendering+=Rendered;
  try{while(Time.realtimeSinceStartup-start<60){if(m.Paused)m.Resume();if(m.Finished){m.SetupScreen();m.StartMatch();}samples.Add(Time.unscaledDeltaTime*1000);if(!screenshot&&Time.realtimeSinceStartup-start>28){screenshot=true;ScreenCapture.CaptureScreenshot(Path.GetFullPath(Folder+"/dense-crowd-actual-player-window.png"));}yield return null;}}
  finally{RenderPipelineManager.endCameraRendering-=Rendered;}
  samples.Sort();Check(samples.Count>100&&renders>100,"sustained sixty-second Windows sample includes automatic gameplay rendering");report.AppendLine("WINDOWS PERF seconds="+(Time.realtimeSinceStartup-start).ToString("F2")+" frames="+samples.Count+" cameraRenders="+renders+" meanMS="+samples.Average().ToString("F2")+" p95MS="+samples[(int)((samples.Count-1)*.95f)].ToString("F2")+" p99MS="+samples[(int)((samples.Count-1)*.99f)].ToString("F2")+" GC0="+(GC.CollectionCount(0)-gc)+" managedDelta="+(GC.GetTotalMemory(false)-memory)+" GPU="+SystemInfo.graphicsDeviceName+" resolution="+Screen.width+"x"+Screen.height+" requestedCap="+Application.targetFrameRate+" vSync="+QualitySettings.vSyncCount+" · timeScale1, uncontrolled host load; no physical-controller or isolated GPU claim");m.SetupScreen();
 }
 IEnumerator SampleFrames(Camera camera,string label){var oldTarget=camera.targetTexture;float oldAspect=camera.aspect;var target=RenderTexture.GetTemporary(1280,720,24,RenderTextureFormat.ARGB32);try{camera.targetTexture=target;camera.aspect=1280f/720;using(var draws=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Draw Calls Count",64))using(var main=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread",64)){long drawSum=0,mainSum=0;int drawSamples=0,mainSamples=0;for(int frame=0;frame<72;frame++){camera.Render();yield return null;if(frame<12)continue;if(draws.Valid&&draws.LastValue>0){drawSum+=draws.LastValue;drawSamples++;}if(main.Valid&&main.LastValue>0){mainSum+=main.LastValue;mainSamples++;}}report.AppendLine("OBSERVATION "+label+" drawSamples="+drawSamples+" meanDraws="+(drawSamples>0?(drawSum/(double)drawSamples).ToString("F1"):"unavailable")+" mainSamples="+mainSamples+" meanMainMs="+(mainSamples>0?(mainSum/(double)mainSamples/1000000).ToString("F2"):"unavailable")+" · controlled paused manual camera, not sustained GPU/frame-budget evidence");}}finally{camera.targetTexture=oldTarget;camera.aspect=oldAspect;RenderTexture.ReleaseTemporary(target);}}
